// ProntoPraIA - Auditoria robusta p/ lote: tolera HTML vazio, erro HTTP (fullResponse) e timeout.
const results = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const url = j.url || j.URL || 'URL desconhecida';
  // Com fullResponse:true o HTTP Request devolve { body, statusCode, headers } em `data`.
  const statusCode = j.data?.statusCode || j.statusCode || null;
  const bodyRaw = (j.data && typeof j.data === 'object' && j.data.body !== undefined) ? j.data.body : (j.data ?? j.html ?? j.body ?? '');
  const html = typeof bodyRaw === 'string' ? bodyRaw : (bodyRaw ? JSON.stringify(bodyRaw) : '');
  const erroHttp = statusCode || j.error || item.error || null;
  // <title> buscado apenas dentro do <head> (evita falso-positivo do body).
  const headMatch = html.match(/<head[^>]*>([\s\S]*?)<\/head>/i);
  const headHtml = headMatch ? headMatch[1] : html;
  let nota = 0;
  const faltando = [];
  const hasTitle = /<title[^>]*>[\s\S]+?<\/title>/i.test(headHtml);
  if (hasTitle) { nota += 25; } else { faltando.push('title'); }
  const hasOgImage = /<meta[^>]+property=["']og:image["'][^>]*>/i.test(html);
  if (hasOgImage) { nota += 25; } else { faltando.push('og:image'); }
  const hasOgPrice = /<meta[^>]+property=["']og:price:amount["'][^>]*>/i.test(html);
  if (hasOgPrice) { nota += 25; } else { faltando.push('og:price:amount'); }
  const hasJsonLd = /<script[^>]+type=["']application\/ld\+json["'][^>]*>/i.test(html);
  if (hasJsonLd) { nota += 25; } else { faltando.push('json-ld'); }
  if (nota > 100) nota = 100;
  let status = 'Crítico';
  if (nota >= 75) status = 'Pronto';
  else if (nota >= 50) status = 'Básico';
  // Status code >= 400 vira 'erro-http: <code>' p/ o PDF consultivo detectar 403/404/500.
  if (typeof statusCode === 'number' && statusCode >= 400 && !faltando.some(f => f.includes('erro-http: ' + statusCode))) {
    faltando.push('erro-http: ' + statusCode);
  }
  if (!html || html.trim() === '') {
    nota = 0; status = 'Crítico';
    if (statusCode) { /* ja registrado acima */ }
    else if (erroHttp) faltando.push('erro-http: ' + String(erroHttp).substring(0, 80));
    else if (!faltando.includes('html-vazio')) faltando.push('html-vazio (bloqueio/timeout?)');
  }
  let prodName = 'Produto exemplo';
  let prodImage = 'https://exemplo.com/imagem.jpg';
  const mTitle = headHtml.match(/<title[^>]*>([^<]+)<\/title>/i);
  if (mTitle && mTitle[1]) prodName = mTitle[1].trim().substring(0, 150);
  const mImg = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i);
  if (mImg && mImg[1]) prodImage = mImg[1];
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Product',
    'name': prodName,
    'image': prodImage,
    'description': 'Descricao do produto em ' + url,
    'brand': { '@type': 'Brand', 'name': 'Marca do produto' },
    'offers': { '@type': 'Offer', 'url': url, 'priceCurrency': 'BRL', 'price': '0.00', 'availability': 'https://schema.org/InStock' }
  };
  results.push({ json: { url, nota, status, faltando: faltando.join(', '), json_ld_sugerido: JSON.stringify(jsonLd) } });
}
return results;

// ProntoPraIA - Persistencia confiavel do CSV via fs.appendFileSync (append real, local).
const fs = require('fs');
const path = require('path');
const CSV_PATH = 'C:\\Users\\User\\Desktop\\prontopraia\\resultados_auditoria.csv';
const HEADER = 'url,nota,status,faltando,json_ld_sugerido';
const filePath = 'C:\\Users\\User\\Desktop\\prontopraia\\resultados_auditoria.csv';
// Neutraliza injecao de formula (CSV injection) e envolve em aspas quando necessario.
function csvEscape(v) {
  let s = String(v ?? '');
  if (/^[=+\-@]/.test(s)) s = "'" + s;
  if (/["\n,]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
}
const lines = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const description = String(j.faltando ?? '');
  lines.push([csvEscape(j.url), csvEscape(j.nota), csvEscape(j.status), csvEscape(description), csvEscape(j.json_ld_sugerido)].join(','));
}
if (!fs.existsSync(filePath)) fs.writeFileSync(filePath, HEADER + '\n', 'utf8');
if (lines.length) fs.appendFileSync(filePath, lines.join('\n') + '\n', 'utf8');
return [{ json: { csv: filePath, linhas_adicionadas: lines.length } }];

